"""
find
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Find(object):
    """
    Find
    """
    def find_and_return_counter_value_from_latest_interval(self, all_intervals_mocs_content,
                                                           moc_to_look_in, required_counter):
        """
        Function to find and return counter value from latest interval
        """
        logger.debug("moc to look in: {}".format(moc_to_look_in))
        logger.debug("Required counter {}".format(required_counter))
        intervals = self._sort_on_intervals(all_intervals_mocs_content)
        for interval in intervals:
            all_mocs_in_interval = all_intervals_mocs_content[interval]
            counter_value = self._find_and_return_counter_values_in_an_interval(
                all_mocs_in_interval, moc_to_look_in, required_counter)
            if counter_value:
                logger.debug("Captured counter value {}".format(counter_value))
                return counter_value
        return None

    def _sort_on_intervals(self, intervals_data):
        intervals = list(intervals_data.keys())
        intervals.sort(reverse=True)
        return intervals

    def _find_and_return_counter_values_in_an_interval(self, all_mocs_content, moc_to_look_in,
                                                       required_counter):
        moc_content = all_mocs_content.get(moc_to_look_in)
        if moc_content:
            return moc_content.get(required_counter)
        return None
